// Integration by MGIS of a behaviour of a library generated by the
// generic-parallel interface of MFront with the hip backend, on points whose
// data are in managed memory, with the consistent tangent operator.
//
// usage: integrate library behaviour number_of_points [hypothesis]
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <span>
#include <string>
#include <vector>
#include <memory_resource>
#include "MGIS/Behaviour/Behaviour.hxx"
#include "MGIS/Behaviour/MaterialDataManager.hxx"
#include "MGIS/Behaviour/Integrate.hxx"
#include "MGIS/MemoryResources/HIPManagedMemoryResource.hxx"

int main(const int argc, const char* const* const argv) {
  using namespace mgis;
  using namespace mgis::behaviour;
  if ((argc != 4) && (argc != 5)) {
    std::fprintf(stderr,
                 "usage: %s library behaviour number_of_points "
                 "[hypothesis]\n",
                 argv[0]);
    return EXIT_FAILURE;
  }
  const auto h = (argc == 5) ? fromString(argv[4]) : Hypothesis::TRIDIMENSIONAL;
  // finite strain behaviours: first Piola-Kirchhoff stress and its
  // derivative with respect to the deformation gradient
  const auto fs = isStandardFiniteStrainBehaviour(argv[1], argv[2]);
  auto o = FiniteStrainBehaviourOptions{};
  o.stress_measure = FiniteStrainBehaviourOptions::PK1;
  o.tangent_operator = FiniteStrainBehaviourOptions::DPK1_DF;
  const auto b = fs ? load(o, argv[1], argv[2], h) : load(argv[1], argv[2], h);
  const auto n = static_cast<size_type>(std::atoi(argv[3]));
  auto managed = memory_resources::HIPManagedMemoryResource{};
  auto i = MaterialDataManagerInitializer{};
  i.location = MemoryLocation::SHARED;
  i.resource = &managed;
  auto m = MaterialDataManager(b, n, i);
  // Young modulus, Poisson ratio and temperature, found by name (the
  // behaviour of ssna303_3d has no material property: its elastic and
  // plastic coefficients are parameters)
  auto values = std::pmr::vector<real>({150e9, 0.3, 293.15}, &managed);
  const auto value = [&values](const std::string& name) {
    const auto names = std::vector<std::string>{"YoungModulus",
                                                "PoissonRatio", "Temperature"};
    for (std::size_t k = 0; k != names.size(); ++k) {
      if (names[k] == name) {
        return std::span<real>(values).subspan(k, 1);
      }
    }
    std::fprintf(stderr, "unexpected variable %s\n", name.c_str());
    std::exit(EXIT_FAILURE);
  };
  for (auto* const s : {&m.s0, &m.s1}) {
    for (const auto& mp : b.mps) {
      setMaterialProperty(*s, mp.name, value(mp.name),
                          MaterialStateManager::EXTERNAL_STORAGE);
    }
    for (const auto& ev : b.esvs) {
      setExternalStateVariable(*s, ev.name, value(ev.name),
                               MaterialStateManager::EXTERNAL_STORAGE);
    }
  }
  // stretch of 1e-3, 2e-3 and 3e-3 along the axes
  const auto gs = getArraySize(b.gradients, b.hypothesis);
  for (size_type p = 0; p != n; ++p) {
    for (size_type c = 0; c != gs; ++c) {
      const auto identity = (fs && c < 3) ? real{1} : real{0};
      m.s0.gradients[p * gs + c] = identity;
      m.s1.gradients[p * gs + c] =
          (c < 3) ? identity + real(1e-3) * static_cast<real>(c + 1) : 0;
    }
  }
  auto opts = BehaviourIntegrationOptions{};
  opts.integration_type =
      IntegrationType::INTEGRATION_CONSISTENT_TANGENT_OPERATOR;
  m.allocateArrayOfTangentOperatorBlocks();
  std::printf("backend %s, %zu points, integration...\n", b.backend.c_str(),
              static_cast<std::size_t>(n));
  std::fflush(stdout);
  const auto t0 = std::chrono::steady_clock::now();
  const auto r = integrate(BatchExecutionPolicy{}, m, opts, 1);
  const auto t1 = std::chrono::steady_clock::now();
  std::printf("status %d in %g ms, stress[2] = %g\n", r.exit_status,
              std::chrono::duration<double, std::milli>(t1 - t0).count(),
              static_cast<double>(m.s1.thermodynamic_forces[2]));
  return r.exit_status == 1 ? EXIT_SUCCESS : EXIT_FAILURE;
}
